<?php /** The recipe form (recipe-add / recipe-edit; ids recipe-form-field-{name}). Data: cur, kind, outputIngredientId, categories, units, locked, globalUnits, back, errors */
$isNew = $cur === null;
$v = static fn (string $k, $d = '') => e((string) ($cur[$k] ?? $d));
?>
<?= view('shared/header.php', ['id' => $isNew ? 'recipe-add' : 'recipe-edit', 'title' => $isNew ? 'New recipe' : 'Edit ' . $cur['name'], 'crumbs' => [['Home', '/'], ['Recipes', '/recipes/'], [$isNew ? 'New' : $cur['name'], null]], 'back' => $back]) ?>
<div class="main-content" id="<?= $isNew ? 'recipe-add' : 'recipe-edit' ?>-content">
    <form method="post" action="/recipes/save.php" hx-post="/recipes/save.php" hx-target="#flash" enctype="multipart/form-data" id="recipe-form" class="card">
        <?= csrf_field() ?>
        <?php if (!$isNew): ?><input type="hidden" name="recipe" value="<?= (int) $cur['recipe_id'] ?>"><?php endif; ?>
        <?php if (!empty($_GET['back'])): ?><input type="hidden" name="return_to" value="<?= e(safe_local_path($_GET['back']) ?? '') ?>"><?php endif; ?>
        <div class="card-body">
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="recipe-form-field-name">Name</label></div><div class="col-lg-8"><input type="text" name="name" id="recipe-form-field-name" class="form-control btn-touch" value="<?= $v('name') ?>" maxlength="120" required></div></div>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="recipe-form-field-code">Code</label></div><div class="col-lg-8"><input type="text" name="code" id="recipe-form-field-code" class="form-control btn-touch" value="<?= $v('code') ?>" maxlength="40" placeholder="from the name"><div class="form-text">R- for a recipe, M- for a modifier, from the name when left blank.</div></div></div>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold">Kind</label></div><div class="col-lg-8"><div class="d-flex flex-wrap gap-2" id="recipe-form-field-kind">
                <?php foreach (RECIPE_KINDS as $k => $l): ?><label class="d-flex align-items-center gap-2 border rounded px-3 btn-touch flex-grow-1" for="recipe-form-field-kind-<?= $k ?>"><input type="radio" class="form-check-input mt-0" name="kind" value="<?= $k ?>" id="recipe-form-field-kind-<?= $k ?>" <?= $kind === $k ? 'checked' : '' ?> <?= $locked ? 'disabled' : '' ?> onchange="document.getElementById('recipe-form-prep').classList.toggle('d-none', this.value !== 'prep'); document.getElementById('recipe-form-portions-unit').classList.toggle('d-none', this.value === 'prep')"><?= e($l) ?></label><?php endforeach; ?>
            </div><?php if ($locked): ?><input type="hidden" name="kind" value="<?= e($kind) ?>"><div class="form-text">Locked: a version was activated or a menu item maps to this recipe.</div><?php endif; ?></div></div>
            <div id="recipe-form-prep" class="<?= $kind === 'prep' ? '' : 'd-none' ?>">
                <?= form_picker('recipe-form', 'output_ingredient', 'Makes stock of', 'ingredient', $outputIngredientId, $errors, ['help' => 'The ingredient this prep makes — the stock, the sauce, the diced onion. It is flagged as a prep.', 'disabled' => $locked]) ?>
            </div>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="recipe-form-field-menu-category">Menu category</label></div><div class="col-lg-8"><select name="menu_category" id="recipe-form-field-menu-category" class="form-select btn-touch"><option value="">None</option><?php foreach ($categories as $c): ?><option value="<?= (int) $c['category_id'] ?>" <?= (string) ($cur['category_id'] ?? '') === (string) $c['category_id'] ? 'selected' : '' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div></div>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="recipe-form-field-portion-qty">One portion is</label></div><div class="col-lg-8"><div class="input-group"><input type="number" step="0.0001" min="0" name="portion_qty" id="recipe-form-field-portion-qty" class="form-control btn-touch" value="<?= $v('portion_qty') ?>" placeholder="220"><select name="portion_unit" id="recipe-form-field-portion-unit" class="form-select btn-touch" style="max-width: 9rem"><option value="">unit</option><?php foreach ($globalUnits as $u): ?><option value="<?= e($u['unit_code']) ?>" <?= ($cur['portion_unit_code'] ?? '') === $u['unit_code'] ? 'selected' : '' ?>><?= e($u['unit_code']) ?></option><?php endforeach; ?></select></div><div class="form-text">Informational — shown on the card.</div></div></div>
            <?php if ($isNew): ?>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="recipe-form-field-batch-yield-qty">One batch makes</label></div><div class="col-lg-8"><div class="input-group"><input type="number" step="0.0001" min="0.0001" name="batch_yield_qty" id="recipe-form-field-batch-yield-qty" class="form-control btn-touch" value="1" required>
                <select name="batch_yield_unit" id="recipe-form-field-batch-yield-unit" class="form-select btn-touch" style="max-width: 12rem" hx-get="/recipes/line-units" hx-trigger="refreshUnits from:#recipe-form-field-output-ingredient" hx-include="#recipe-form-field-output-ingredient" hx-swap="innerHTML"><?php if ($kind === 'prep' && $units !== []): foreach ($units as $u): ?><option value="<?= e($u['code']) ?>"><?= e($u['label']) ?></option><?php endforeach; else: ?><option value="portion">portion(s)</option><?php endif; ?></select>
                <span id="recipe-form-portions-unit" class="d-none"></span></div><div class="form-text">A prep: the output's unit (4 l). A menu item or a modifier: portions.</div></div></div>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="recipe-form-field-expected-loss-pct">Expected loss %</label></div><div class="col-lg-8"><input type="number" step="0.01" min="0" max="99.99" name="expected_loss_pct" id="recipe-form-field-expected-loss-pct" class="form-control btn-touch" value="0"><div class="form-text">Cook loss on the batch as a whole — the net yield is what the batch makes.</div></div></div>
            <?php endif; ?>
            <div class="row mb-3"><div class="col-lg-4"><label class="fw-semibold" for="recipe-form-field-method">Method</label></div><div class="col-lg-8"><textarea name="method" id="recipe-form-field-method" class="form-control" rows="6" maxlength="20000"><?= $v('method') ?></textarea></div></div>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="recipe-form-field-photo">Photo</label></div><div class="col-lg-8"><input type="file" name="photo" id="recipe-form-field-photo" class="form-control btn-touch" accept="image/*"></div></div>
            <?php if (!$isNew): ?>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold">Status</label></div><div class="col-lg-8"><div class="d-flex gap-2" id="recipe-form-field-status"><label class="border rounded px-3 btn-touch d-flex align-items-center gap-2 flex-grow-1" for="recipe-form-field-status-active"><input type="radio" class="form-check-input mt-0" name="status" value="active" id="recipe-form-field-status-active" <?= $cur['active'] ? 'checked' : '' ?>>Active</label><label class="border rounded px-3 btn-touch d-flex align-items-center gap-2 flex-grow-1" for="recipe-form-field-status-archived"><input type="radio" class="form-check-input mt-0" name="status" value="archived" id="recipe-form-field-status-archived" <?= $cur['active'] ? '' : 'checked' ?>>Archived</label></div></div></div>
            <?php endif; ?>
        </div>
        <div class="card-footer d-flex gap-2"><button type="submit" class="btn btn-primary btn-touch" id="recipe-form-save-btn"><?= $isNew ? 'Make the recipe and open its draft' : 'Save' ?></button><?= hx_link($isNew ? '/recipes/' : '/recipes/' . (int) $cur['recipe_id'], 'Cancel', 'btn btn-light btn-touch', 'id="recipe-form-cancel"') ?></div>
    </form>
</div>
<script>(function(){var o=document.getElementById('recipe-form-field-output-ingredient');if(o){o.addEventListener('change',function(){htmx.trigger(o,'refreshUnits');});}})();</script>
